/*
 * The boot menu of the shim, v0.1: full-screen selector with exact logos.
 *
 * v0 was a band over the diagnostic console to prove the drawing; this
 * version paints its own full screen: a title, one card per choice with
 * a logo and the label, and a countdown that keeps the default (iOS).
 * The logos are one-bit silhouettes in shim/menu_logos.h, generated by
 * tools/gen-menu-logos.py from the vector sources of Bootstrap (apple,
 * MIT) and Google Material (android head, Apache 2.0) -- credited in the
 * generated header.
 *
 * There is still no input: the volume and power keys are polled in a
 * later version -- the PON and the gpio of the volume come out of the
 * live tree, and shim/spmi.c prints their status bytes after the menu
 * so a pressed-key photo identifies the bits that move. What v0.1 keeps
 * proving is that the drawing survives until the kernel's own console
 * takes the framebuffer over and the loader boots the same kernel as
 * always.
 *
 * No absolute addresses in .rodata (the image is linked at 0 and loaded
 * wherever ABL puts it): the strings are char arrays, the bitmaps are
 * referenced by their PC-relative section base, and the font is reached
 * like console.c reaches it. The geometry uses the board table
 * constants (FB_*), which is what the console itself runs at
 * (BOARD_FB_FROM_DTB is 0 on both boards).
 */
#include <stdint.h>
#include "board.h"
#include "console.h"
#include "font.h"
#include "menu.h"
#include "menu_logos.h"
#include "spmi.h"

#define M_BG		0xff10101aU	/* the page */
#define M_CARD		0xff191922U	/* an unselected card */
#define M_CARD_LINE	0xff2e2e3aU	/* its border */
#define M_FG		0xffffffffU
#define M_HI_BG		0xff00c864U	/* the selected card's accent */
#define M_HI_FG		0xff001014U	/* its label */
#define M_DIM		0xff8a8a96U	/* the notes under the choices */
#define M_CD		0xffffff00U	/* the countdown */
#define M_APPLE		0xffffffffU	/* the fruit, white (user's pick) */
#define M_DROID		0xff3ddc84U	/* the robot, the Android green */
#define M_WHITE		0xffffffffU	/* every text of the menu */

#define M_SCALE_TITLE	5
#define M_SCALE_ITEM	5
#define M_SCALE_NOTE	2
#define M_SCALE_CD	6

#define M_CARD_W	600
#define M_CARD_H	900
#define M_CARD_Y	420
#define M_CARD_GAP	120
#define M_LOGO_Y	90		/* logo offset inside the card */
#define M_LABEL_Y	470		/* label offset inside the card */
#define M_NOTE_Y	600		/* note offset inside the card */

/* A filled rectangle. */
static void
m_rect(int x, int y, int w, int h, uint32_t c)
{
	if (!con_fb)
		return;
	if (x + w > FB_W)
		w = FB_W - x;
	if (y + h > FB_H)
		h = FB_H - y;
	for (int i = 0; i < h; i++) {
		volatile uint32_t *line = con_fb +
		    (uint64_t)(y + i) * (FB_STRIDE / 4);
		for (int j = 0; j < w; j++)
			line[x + j] = c;
	}
}

/* The border of a rectangle: four strips, thickness t. */
static void
m_ring(int x, int y, int w, int h, int t, uint32_t c)
{
	m_rect(x, y, w, t, c);
	m_rect(x, y + h - t, w, t, c);
	m_rect(x, y + t, t, h - 2 * t, c);
	m_rect(x + w - t, y + t, t, h - 2 * t, c);
}

/* One scaled glyph, foreground only (the caller paints the background). */
static void
m_glyph(int x, int y, char ch, int scale, uint32_t fg)
{
	if (ch < 0x20 || ch > 0x7e)
		ch = '?';
	const unsigned char *g = font8x16[ch - 0x20];
	if (x + 8 * scale > FB_W || y + 16 * scale > FB_H)
		return;
	for (int gy = 0; gy < 16; gy++)
		for (int gx = 0; gx < 8; gx++) {
			if (!(g[gy] & (0x80 >> gx)))
				continue;
			for (int sy = 0; sy < scale; sy++) {
				volatile uint32_t *p = con_fb +
				    (uint64_t)(y + gy * scale + sy) *
				    (FB_STRIDE / 4) + x + gx * scale;
				for (int sx = 0; sx < scale; sx++)
					p[sx] = fg;
			}
		}
}

static int
m_w(const char *s, int scale)
{
	int n = 0;

	while (s[n])
		n++;
	return n * 8 * scale;
}

static int
m_str(int x, int y, const char *s, int scale, uint32_t fg)
{
	for (int i = 0; s[i]; i++) {
		m_glyph(x, y, s[i], scale, fg);
		x += 8 * scale;
	}
	return x;
}

/* A line centered on the screen width. */
static void
m_center(int y, const char *s, int scale, uint32_t fg)
{
	int x = (FB_W - m_w(s, scale)) / 2;

	if (x < 24)
		x = 24;
	m_str(x, y, s, scale, fg);
}

/* A line centered inside the box the card occupies. */
static void
m_in(int cx, int cw, int y, const char *s, int scale, uint32_t fg)
{
	int x = cx + (cw - m_w(s, scale)) / 2;

	if (x < cx + 16)
		x = cx + 16;
	m_str(x, y, s, scale, fg);
}

/* A one-bit bitmap, scaled; both colors are painted (the logo is opaque). */
static void
m_blit(int x, int y, const unsigned char *bits, int w, int h, int scale,
    uint32_t fg, uint32_t bg)
{
	int stride = (w + 7) / 8;

	if (!con_fb)
		return;
	for (int gy = 0; gy < h; gy++)
		for (int gx = 0; gx < w; gx++) {
			uint32_t c = (bits[stride * gy + (gx >> 3)] &
			    (0x80 >> (gx & 7))) ? fg : bg;

			for (int sy = 0; sy < scale; sy++) {
				int py = y + gy * scale + sy;
				int px = x + gx * scale;

				if (py >= FB_H || px >= FB_W)
					continue;
				volatile uint32_t *p = con_fb +
				    (uint64_t)py * (FB_STRIDE / 4) + px;
				for (int sx = 0; sx < scale && px + sx < FB_W;
				    sx++)
					p[sx] = c;
			}
		}
}

static uint64_t
m_ticks(void)
{
	uint64_t t;

	__asm__ volatile("isb; mrs %0, cntpct_el0" : "=r"(t));
	return t;
}

static void
m_wait_ms(int ms)
{
	uint64_t f;

	__asm__ volatile("mrs %0, cntfrq_el0" : "=r"(f));
	uint64_t end = m_ticks() + f / 1000 * ms;
	while (m_ticks() < end)
		;
}

/* One choice: card, logo, label, note; the selected one gets the accent. */
static void
m_card(int cx, const unsigned char *bits, int bw, int bh, int scale,
    int slab_h, const char *label, const char *note, int sel)
{
	int lw = bw * scale, lh = bh * scale, my;

	m_rect(cx, M_CARD_Y, M_CARD_W, M_CARD_H, M_CARD);
	if (sel)
		m_ring(cx, M_CARD_Y, M_CARD_W, M_CARD_H, 8, M_HI_BG);
	else
		m_ring(cx, M_CARD_Y, M_CARD_W, M_CARD_H, 3, M_CARD_LINE);

	/* The logo, vertically centered on the tallest logo's slab. */
	my = M_CARD_Y + M_LOGO_Y + (slab_h - lh) / 2;
	m_blit(cx + (M_CARD_W - lw) / 2, my, bits, bw, bh, scale,
	    bits == m_apple ? M_APPLE : M_DROID, M_CARD);

	/* The label: white on both cards; the accent ring is the mark. */
	m_in(cx, M_CARD_W, M_CARD_Y + M_LABEL_Y, label, M_SCALE_ITEM,
	    M_WHITE);

	/* The note under the label. */
	m_in(cx, M_CARD_W, M_CARD_Y + M_NOTE_Y, note, M_SCALE_NOTE, M_WHITE);
}

/* The title and the two cards: everything a selection change repaints. */
static void
m_screen(int sel)
{
	static const char title[] = BOARD_NAME " boot menu";
	static const char items[][8] = { "iOS", "Android" };
	static const char notes[][48] = {
		"the root image lives in userdata",
		"not wired yet (v2: misc write)",
	};

	m_rect(0, 0, FB_W, FB_H, M_BG);
	m_center(140, title, M_SCALE_TITLE, M_WHITE);
	/* Two cards centered as a pair: 60 + 600 + 120 + 600 + 60. The
	 * logos share a slab of three times the fruit's height. */
	m_card(60, m_apple, m_apple_W, m_apple_H, 3, m_apple_H * 3,
	    items[0], notes[0], sel == 0);
	m_card(780, m_android, m_android_W, m_android_H, 3, m_apple_H * 3,
	    items[1], notes[1], sel == 1);
}

/* One line of key state at the bottom, for the next photograph. */
static void
m_keys_line(unsigned char pon, unsigned char gpio, int ready)
{
	static const char hex[] = "0123456789abcdef";
	char buf[40];

	buf[0] = 'k';
	buf[1] = 'e';
	buf[2] = 'y';
	buf[3] = 's';
	buf[4] = ' ';
	buf[5] = ready ? 'o' : 'o';
	buf[6] = ready ? 'n' : 'f';
	buf[7] = ready ? ' ' : 'f';
	buf[8] = ready ? 'p' : ' ';
	buf[9] = ready ? 'o' : ' ';
	buf[10] = ready ? 'n' : ' ';
	buf[11] = ready ? '=' : ' ';
	buf[12] = ready ? hex[pon >> 4] : ' ';
	buf[13] = ready ? hex[pon & 15] : ' ';
	buf[14] = ' ';
	buf[15] = ready ? 'g' : ' ';
	buf[16] = ready ? '=' : ' ';
	buf[17] = ready ? hex[gpio >> 4] : ' ';
	buf[18] = ready ? hex[gpio & 15] : ' ';
	buf[19] = 0;
	m_rect(0, 3000, FB_W, 32, M_BG);
	m_str(24, 3000, buf, 2, M_WHITE);
	if (!ready) {
		static const char tag[] = "spmi code ";
		char nb[8];
		int w = spmi_why(), n = 0;

		if (w >= 10)
			nb[n++] = (char)('0' + w / 10);
		nb[n++] = (char)('0' + w % 10);
		nb[n] = 0;
		m_rect(0, 3020, FB_W, 32, M_BG);
		m_str(24, 3020, tag, 2, M_WHITE);
		m_str(24 + 10 * 8 * 2, 3020, nb, 2, M_WHITE);
	}
}

int
menu_show(uintptr_t fdt)
{
	static const char leaving[] = "LEAVES IT AS IT IS: starting iOS";
	static const char cd_head[] = "starting iOS in ";
	char cd_line[20];
	int sel = MENU_DEFAULT;
	int cd_y = 2700;
	int ready;
	unsigned char pon = 0, gpio = 0;
	int page = 0, shown = -1, elapsed = 0;

	if (!con_fb)
		return sel;

	/*
	 * The keys. shim/spmi.c takes the arbiter regions and the two
	 * peripherals out of the live tree; a failed probe leaves the
	 * countdown as the only path, so the menu never depends on the
	 * keys to produce a boot.
	 */
	spmi_init(fdt);
	ready = spmi_ready();
	if (ready)
		(void)spmi_poll(&pon, &gpio, &page);

	m_screen(sel);
	m_keys_line(pon, gpio, ready);

	/* One second of countdown, polled at 50 ms: an ascending edge of
	 * any PON bit other than bit 0 moves the selection, an ascending
	 * bit 0 of the PON (KPDPWR) confirms. Rising edges keep a press
	 * from cycling twice (press then release). */
	while (elapsed < MENU_SECONDS * 1000) {
		m_wait_ms(50);
		elapsed += 50;

		if (ready) {
			unsigned char p = 0, g = 0;
			int e = spmi_poll(&p, &g, &page);

			/* spmi.c reports RISING bits only: bit 0 of the PON
			 * is KPDPWR (the power key: confirm); any other
			 * rising bit moves the selection (the volume). */
			if ((e & SPMI_PON_ANY) && (g & 1)) {
				m_rect(0, cd_y, FB_W, 16 * M_SCALE_CD,
				    M_BG);
				m_center(cd_y, leaving, M_SCALE_CD, M_WHITE);
				return sel;
			}
			if (e) {
				sel = 1 - sel;
				m_screen(sel);
			}
			pon = p;
			gpio = g;
			m_keys_line(pon, gpio, ready);
		}

		int left = MENU_SECONDS - elapsed / 1000;

		if (left < 0)
			left = 0;
		if (left != shown) {
			char *cp = cd_line;
			const char *q = cd_head;

			shown = left;
			while (*q)
				*cp++ = *q++;
			*cp++ = (char)('0' + (left > 9 ? 9 : left));
			*cp++ = 's';
			*cp = 0;
			m_rect(0, cd_y, FB_W, 16 * M_SCALE_CD, M_BG);
			m_center(cd_y, cd_line, M_SCALE_CD, M_WHITE);
		}
	}
	m_rect(0, cd_y, FB_W, 16 * M_SCALE_CD, M_BG);
	m_center(cd_y, leaving, M_SCALE_CD, M_WHITE);

	return sel;
}
